// Animated audience. Two low-poly rigged people built from MakeHuman's CC0
// assets (public/models/crowd.glb: a male and a female body with Idle / Cheer
// / Jump / Wave clips, all generated by tools/build-humans.ts) are loaded once
// and every clip keyframe is baked into a morph target, so each body is a
// single InstancedMesh: a spectator picks a clip and the GPU blends the two
// nearest keyframes per instance (InstancedMesh.setMorphAt). A 3x2 atlas of
// skin tones with the outfit painted in, plus a per-instance shirt tint, gives
// everyone a different look. Two draw calls for the whole stand.
//
// Everyone runs the same animation uniformly - when something happens on court
// the whole stand gets one clip - but each person plays it at their own
// slightly shifted frequency, which also drifts slowly over time, so hundreds
// of people cheer together without moving in lockstep.
import * as THREE from './three.ts';
import { GLTFLoader } from 'three/examples/jsm/loaders/GLTFLoader.js';
import type { GLTF } from 'three/examples/jsm/loaders/GLTFLoader.js';

const MODEL_URL = `${import.meta.env.BASE_URL}models/crowd.glb`;
/** the atlas: columns are skin tones, rows are the bodies (male, female) - see tools/build-humans.ts */
const TILE_COLS = 3,
  TILE_ROWS = 2;
/** clips baked, with the number of keyframes each gets (sum = morph target count) */
const CLIPS: { name: string; frames: number }[] = [
  { name: 'Idle', frames: 5 },
  { name: 'Cheer', frames: 7 },
  { name: 'Jump', frames: 8 },
  { name: 'Wave', frames: 6 },
];
const IDLE = 0,
  CHEER = 1,
  JUMP = 2,
  WAVE = 3;
/** each person's playback frequency sits within this fraction of the shared tempo */
const FREQ_SPREAD = 0.14;
/** and wanders by this much, this fast (rad/s), so the spread keeps shifting */
const DRIFT = 0.08,
  DRIFT_RATE = 0.35;

interface BakedClip {
  start: number;
  frames: number;
  duration: number;
}

interface Body {
  name: string;
  geometry: THREE.BufferGeometry;
  clips: BakedClip[];
}

interface Baked {
  bodies: Body[];
  atlas: THREE.Texture;
}

export interface Spot {
  pos: THREE.Vector3;
  /** rotation about Y so the person faces the court */
  yaw: number;
  /** shirt colour */
  color: THREE.Color;
}

interface Person {
  body: number;
  /** instance index within the body's mesh */
  slot: number;
  clip: number;
  /** clip time, advanced at this person's own frequency */
  time: number;
  /** playback frequency relative to the shared tempo */
  freq: number;
  driftPhase: number;
  /** time at which to pick the next clip */
  until: number;
  /** how keen this one is to join in (0..1) */
  keen: number;
}

const _v = new THREE.Vector3();

let bakeLoad: Promise<Baked | null> | null = null;

function loadBaked(): Promise<Baked | null> {
  bakeLoad ??= new GLTFLoader()
    .loadAsync(MODEL_URL)
    .then(bake)
    .catch((e: unknown) => {
      console.warn('crowd model failed to load', e);
      return null;
    });
  return bakeLoad;
}

/** Sample every skinned body through each clip and store every keyframe as a morph target. */
function bake(gltf: GLTF): Baked {
  const skins: THREE.SkinnedMesh[] = [];
  gltf.scene.traverse((o) => {
    if ((o as THREE.SkinnedMesh).isSkinnedMesh) skins.push(o as THREE.SkinnedMesh);
  });
  if (!skins.length) throw new Error('crowd model has no skinned mesh');
  const mixer = new THREE.AnimationMixer(gltf.scene);
  const targets: Float32Array[][] = skins.map(() => []);
  const clips: BakedClip[] = [];

  for (const def of CLIPS) {
    const clip = gltf.animations.find((c) => c.name === def.name) ?? gltf.animations[0];
    const action = mixer.clipAction(clip);
    action.play();
    clips.push({ start: targets[0].length, frames: def.frames, duration: clip.duration });
    for (let f = 0; f < def.frames; f++) {
      mixer.setTime((f / def.frames) * clip.duration);
      gltf.scene.updateMatrixWorld(true);
      skins.forEach((skin, s) => {
        skin.skeleton.update();
        const src = skin.geometry.attributes.position;
        const arr = new Float32Array(src.count * 3);
        for (let i = 0; i < src.count; i++) {
          _v.fromBufferAttribute(src, i);
          skin.applyBoneTransform(i, _v);
          _v.applyMatrix4(skin.matrixWorld);
          arr[i * 3] = _v.x;
          arr[i * 3 + 1] = _v.y;
          arr[i * 3 + 2] = _v.z;
        }
        targets[s].push(arr);
      });
    }
    action.stop();
    mixer.uncacheAction(clip);
  }

  const bodies = skins.map((skin, s): Body => {
    const src = skin.geometry;
    const geometry = new THREE.BufferGeometry();
    if (src.index) geometry.setIndex(src.index.clone());
    geometry.setAttribute('position', new THREE.BufferAttribute(targets[s][0].slice(), 3));
    if (src.attributes.uv) geometry.setAttribute('uv', src.attributes.uv.clone());
    geometry.computeVertexNormals();
    geometry.morphTargetsRelative = false;
    geometry.morphAttributes.position = targets[s].map((t) => new THREE.BufferAttribute(t, 3));
    geometry.computeBoundingSphere();
    // the sphere must cover a jump too
    geometry.boundingSphere!.radius += 0.6;
    return { name: skin.name, geometry, clips };
  });
  const atlas = (skins[0].material as THREE.MeshStandardMaterial).map;
  if (!atlas) throw new Error('crowd model has no atlas texture');
  return { bodies, atlas };
}

/**
 * One material for every spectator: the atlas tile is chosen per instance
 * (aTile), and the instance colour tints only where the atlas alpha marks the
 * shirt, so skin keeps its tone.
 */
function crowdMaterial(atlas: THREE.Texture): THREE.MeshStandardMaterial {
  const mat = new THREE.MeshStandardMaterial({ map: atlas, roughness: 0.9 });
  mat.onBeforeCompile = (shader) => {
    shader.uniforms.uTileScale = { value: new THREE.Vector2(1 / TILE_COLS, 1 / TILE_ROWS) };
    shader.vertexShader = shader.vertexShader
      .replace('#include <common>', '#include <common>\nattribute vec2 aTile;\nuniform vec2 uTileScale;')
      .replace('#include <uv_vertex>', '#include <uv_vertex>\n#ifdef USE_MAP\n\tvMapUv = vMapUv * uTileScale + aTile;\n#endif');
    shader.fragmentShader = shader.fragmentShader.replace(
      '#include <color_fragment>',
      '#if defined( USE_COLOR ) || defined( USE_COLOR_ALPHA )\n\tdiffuseColor.rgb *= mix( vec3( 1.0 ), vColor.rgb, diffuseColor.a );\n#endif\n\tdiffuseColor.a = 1.0;',
    );
  };
  return mat;
}

/** A stand full of people who idle, wave, and jump up when something happens. */
export class Crowd {
  group = new THREE.Group();
  private spots: Spot[];
  private people: Person[] = [];
  private meshes: { mesh: THREE.InstancedMesh; proxy: THREE.Mesh; body: Body }[] = [];
  private excitedUntil = -1;
  /** the one clip the whole stand does while excited */
  private uniformClip = CHEER;
  /** keenness needed to join in */
  private keenNeeded = 0;
  private time = 0;
  private lastTime = -1;
  private seed = 12345;

  constructor(spots: Spot[]) {
    this.spots = spots;
    void loadBaked().then((b) => {
      if (b) this.build(b);
    });
  }

  private rnd(): number {
    this.seed = (this.seed * 16807) % 2147483647;
    return this.seed / 2147483647;
  }

  private build(baked: Baked): void {
    const mat = crowdMaterial(baked.atlas);
    // deal the spots between the bodies
    const assign: number[][] = baked.bodies.map(() => []);
    this.spots.forEach((_, i) => assign[Math.floor(this.rnd() * baked.bodies.length)].push(i));
    const dummy = new THREE.Object3D();
    baked.bodies.forEach((body, b) => {
      const list = assign[b];
      if (!list.length) return;
      const mesh = new THREE.InstancedMesh(body.geometry, mat, list.length);
      const tiles = new Float32Array(list.length * 2);
      list.forEach((si, slot) => {
        const sp = this.spots[si];
        dummy.position.copy(sp.pos);
        // spot yaws point +Z at the court; the bodies face -Z (like the opponent model)
        dummy.rotation.set(0, sp.yaw + Math.PI, 0);
        const sc = 0.94 + this.rnd() * 0.12;
        dummy.scale.set(sc, sc, sc);
        dummy.updateMatrix();
        mesh.setMatrixAt(slot, dummy.matrix);
        mesh.setColorAt(slot, sp.color);
        tiles[slot * 2] = Math.floor(this.rnd() * TILE_COLS) / TILE_COLS;
        tiles[slot * 2 + 1] = b / TILE_ROWS;
        this.people.push({ body: b, slot, clip: IDLE, time: this.rnd() * 4, freq: 1 + (this.rnd() - 0.5) * 2 * FREQ_SPREAD, driftPhase: this.rnd() * Math.PI * 2, until: this.rnd() * 4, keen: this.rnd() });
      });
      body.geometry.setAttribute('aTile', new THREE.InstancedBufferAttribute(tiles, 2));
      mesh.computeBoundingSphere();
      // carries morphTargetInfluences for setMorphAt
      this.meshes.push({ mesh, proxy: new THREE.Mesh(body.geometry), body });
      this.group.add(mesh);
    });
  }

  /** Something happened on court: 1 = a point, 2 = a game, 3 = the match. */
  excite(level: number): void {
    level = Math.min(3, level);
    this.excitedUntil = this.time + 1.6 + level * 1.1;
    // the whole stand does the same thing: a cheer for a point, a jump for a game or the match
    this.uniformClip = level >= 2 ? JUMP : CHEER;
    this.keenNeeded = 0.35 + level * 0.22;
    // everyone keen enough re-rolls within the next half second, with a ripple of delays
    for (const p of this.people) if (p.keen < this.keenNeeded) p.until = Math.min(p.until, this.time + this.rnd() * 0.5);
  }

  update(t: number): void {
    const dt = this.lastTime < 0 ? 0 : Math.min(0.1, Math.max(0, t - this.lastTime));
    this.lastTime = t;
    this.time = t;
    if (!this.meshes.length) return;
    const excited = t < this.excitedUntil;
    for (const p of this.people) {
      const { body, proxy } = this.meshes[p.body];
      if (t >= p.until) this.pickNext(p, excited);
      const c = body.clips[p.clip];
      // the same clip for everyone, at this person's own shifting frequency
      const drift = 1 + DRIFT * Math.sin(t * DRIFT_RATE + p.driftPhase);
      p.time += dt * p.freq * drift;
      const u = ((p.time % c.duration) / c.duration) * c.frames;
      const f0 = Math.floor(u) % c.frames;
      const f1 = (f0 + 1) % c.frames;
      const w = u - Math.floor(u);
      const inf = proxy.morphTargetInfluences!;
      inf.fill(0);
      inf[c.start + f0] = 1 - w;
      inf[c.start + f1] = w;
      this.meshes[p.body].mesh.setMorphAt(p.slot, proxy);
    }
    for (const { mesh } of this.meshes) if (mesh.morphTexture) mesh.morphTexture.needsUpdate = true;
  }

  private pickNext(p: Person, excited: boolean): void {
    let clip = IDLE;
    if (excited) {
      if (p.keen < this.keenNeeded) clip = this.uniformClip;
    } else {
      const r = this.rnd();
      if (r < 0.05) clip = WAVE;
      else if (r < 0.08) clip = CHEER;
    }
    const c = this.meshes[p.body].body.clips[clip];
    if (clip !== p.clip) {
      p.clip = clip;
      // start the new clip from its first frame, a touch out of step with the neighbours
      p.time = this.rnd() * 0.08;
    }
    const loops = clip === IDLE ? 1 + Math.floor(this.rnd() * 3) : 1 + Math.floor(this.rnd() * 2);
    p.until = this.time + (c.duration / p.freq) * loops;
  }
}
